
// ---------- Icons.js ----------
// Icons - SVG 圖示元件
const Icons = {
    ArrowUp: ({ className }) => <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="m5 12 7-7 7 7" /><path d="M12 19V5" /></svg>,
    ArrowDown: ({ className }) => <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M12 5v14" /><path d="m19 12-7 7-7-7" /></svg>,
    Minus: ({ className }) => <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M5 12h14" /></svg>,
    Database: ({ className }) => <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><ellipse cx="12" cy="5" rx="9" ry="3" /><path d="M21 12c0 1.66-4 3-9 3s-9-1.34-9-3" /><path d="M3 5v14c0 1.66 4 3 9 3s9-1.34 9-3V5" /></svg>,
    ExternalLink: ({ className }) => <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6" /><polyline points="15 3 21 3 21 9" /><line x1="10" x2="21" y1="14" y2="3" /></svg>,
    ChevronLeft: ({ className }) => <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="m15 18-6-6 6-6" /></svg>,
    ChevronRight: ({ className }) => <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="m9 18 6-6-6-6" /></svg>,
    Calendar: ({ className }) => <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><rect width="18" height="18" x="3" y="4" rx="2" ry="2" /><line x1="16" x2="16" y1="2" y2="6" /><line x1="8" x2="8" y1="2" y2="6" /><line x1="3" x2="21" y1="10" y2="10" /></svg>,
    X: ({ className }) => <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M18 6 6 18" /><path d="m6 6 12 12" /></svg>,
    Users: ({ className }) => <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2" /><circle cx="9" cy="7" r="4" /><path d="M22 21v-2a4 4 0 0 0-3-3.87" /><path d="M16 3.13a4 4 0 0 1 0 7.75" /></svg>,
    User: ({ className }) => <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2" /><circle cx="12" cy="7" r="4" /></svg>,
    Shield: ({ className }) => <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10" /><path d="m9 12 2 2 4-4" /></svg>,
    Sword: ({ className }) => <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><polyline points="14.5 17.5 3 6 3 3 6 3 17.5 14.5" /><line x1="13" x2="19" y1="19" y2="13" /><line x1="16" x2="20" y1="16" y2="20" /><line x1="19" x2="21" y1="21" y2="19" /></svg>,
    BarChart: ({ className }) => <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><line x1="18" x2="18" y1="20" y2="10" /><line x1="12" x2="12" y1="20" y2="4" /><line x1="6" x2="6" y1="20" y2="14" /></svg>
};

window.Icons = Icons;


// ---------- ui.js ----------
// 共用介面元件（設計系統）：window.UI
// 風格：細線分隔的數據表（ledger）取代盒狀卡片；大數字用 font-display（Barlow Condensed），
// 標籤一律「中文 + 小字 NBA 原文」。Tailwind class 必須完整寫在這裡（CLI 掃不到字串拼接）。
//   StatCell  單一指標格（數值三態：真的 0 照常顯示／無資料「—」／不適用「—」+ tooltip）
//   Ledger    StatCell 的容器（外框上/左線 + 每格右/下線，空位不畫線）
//   PctBar    百分位色階條（紅 → 月光銀 → 綠，中線 = 聯盟中位）；只給「真的有 percentile」的資料用
//   Seg       膠囊分段切換（aria-pressed）
//   TabBar    sticky 分頁列（章節列／薪資頁／單場頁共用）＋ useTabKeys 數字鍵切分頁
//   Section   區塊（標題＋小字原文＋說明＋右側操作），Note 空狀態／提示，Chip/selectClass 篩選膠囊
//   ExpandRow 可橫捲表格的展開列（內容固定在可視寬度，手機不會跑到畫面外）
//   寫作工具  CopyBtn/citeLine/doCopy（複製引用）、Info（指標定義，讀 glossary.js；帶 cite 時小卡內含複製引用）、toast、ExportMenu/exportCSV/exportPNG（匯出）
//   DataTable 可排序表格（Synergy 式：數字右對齊等寬、首欄在手機橫捲時固定且限寬換行，避免長名稱蓋住數字）
window.UI = (function () {
    // 「切入次數 (Drives)」→ ['切入次數', 'Drives']；沒有括號就整串當中文
    const splitTitle = (title) => {
        const m = String(title || '').match(/^(.*?)\s*\(([^()]*)\)\s*$/);
        return m ? [m[1], m[2]] : [String(title || ''), null];
    };

    // 0–100 → 紅(#EF4444) / 月光銀(#C4CED2) / 綠(#12A150) 線性內插
    const RED = [239, 68, 68], SILVER = [196, 206, 210], GREEN = [18, 161, 80];
    const mix = (a, b, t) => a.map((v, i) => Math.round(v + (b[i] - v) * t));
    const pctColor = (p) => {
        const v = Math.max(0, Math.min(100, p)) / 100;
        const c = v < 0.5 ? mix(RED, SILVER, v / 0.5) : mix(SILVER, GREEN, (v - 0.5) / 0.5);
        return `rgb(${c[0]}, ${c[1]}, ${c[2]})`;
    };

    const isBlank = (v) => v == null || v === '';

    // 漲跌：betterIsLarger=false 時（失誤、對手命中率…）下降才是好
    const Delta = ({ value, prevValue, unit = '', betterIsLarger = true, digits = 1 }) => {
        if (isBlank(value) || isBlank(prevValue)) return null;
        const d = +(Number(value) - Number(prevValue)).toFixed(digits);
        if (!d) return null;
        const good = (d > 0) === betterIsLarger;
        return (
            <span className={`font-mono text-[10px] tabular-nums whitespace-nowrap ${good ? 'text-[#12A150]' : 'text-[#EF4444]'}`}>
                {d > 0 ? '▲' : '▼'} {Math.abs(d).toFixed(digits)}{unit}
            </span>
        );
    };

    const PctBar = ({ value, label = 'PR' }) => {
        if (typeof value !== 'number') return null;
        const v = Math.max(0, Math.min(100, value));
        const color = pctColor(v);
        return (
            <div className="mt-2.5">
                <div className="flex justify-between font-mono text-[10px] text-slate-500" title="聯盟百分位（Percentile，0–100，越高越好；中線為聯盟中位數）">
                    <span>{label}</span>
                    <span className="tabular-nums" style={{ color }}>{v.toFixed(1)}</span>
                </div>
                <div className="relative h-[3px] mt-1 bg-white/[0.08]">
                    <div className="absolute inset-y-0 left-0" style={{ width: v + '%', background: color }}></div>
                    <div className="absolute -top-[2px] left-1/2 h-[7px] w-px bg-slate-400/50" title="聯盟中位數"></div>
                </div>
            </div>
        );
    };

    // ── 寫作工具：複製引用、指標定義 ──
    // 引用的「主體／賽季／日期」由 App 每次 render 寫入 window.CiteCtx：
    //   { subject, season, asOfSnap（快照日期）, asOfAgg（逐場重算的截至日期）, isHistory }
    // 每日快照的數字引用快照日；GameAgg 逐場重算的平均引用截至日——兩者可能不同，不可混用
    const copyText = async (text) => {
        try { await navigator.clipboard.writeText(text); return true; }
        catch (e) {
            try {   // 舊瀏覽器 / 非安全來源退回 execCommand
                const ta = document.createElement('textarea'); ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
                document.body.appendChild(ta); ta.select(); const ok = document.execCommand('copy'); ta.remove(); return ok;
            } catch (e2) { return false; }
        }
    };
    let toastTimer = null;
    const toast = (msg) => {
        let el = document.getElementById('wl-toast');
        if (!el) {
            el = document.createElement('div'); el.id = 'wl-toast'; el.setAttribute('role', 'status');
            el.style.cssText = 'position:fixed;left:50%;bottom:24px;transform:translateX(-50%);z-index:60;max-width:min(92vw,560px);padding:10px 16px;background:#0C1A2E;border:1px solid rgba(255,255,255,.18);color:#F8FAFC;font-size:13px;line-height:1.5;box-shadow:0 8px 24px rgba(0,0,0,.4);transition:opacity .2s;';
            document.body.appendChild(el);
        }
        el.textContent = msg; el.style.opacity = '1';
        clearTimeout(toastTimer); toastTimer = setTimeout(() => { el.style.opacity = '0'; }, 2600);
    };
    // 組引用句：主體｜賽季｜日期或期間｜指標（原文） 數值（聯盟第N）｜資料：來源
    // rank：window.leagueRank／ptRank 回傳的 { rank, n }，有給才在數值後加名次
    const citeLine = ({ label, en, value, unit = '', gkey, asOf = 'snap', note, rank }) => {
        const c = window.CiteCtx || {};
        const g = (window.GLOSSARY || {})[gkey] || {};
        const when = asOf === 'none' ? null : c.isHistory ? '期末快照' : (asOf === 'agg' ? c.asOfAgg : c.asOfSnap);
        // 最後附上當下畫面的網址（hash 記住球員/章節/賽季/日期），日後可從引用直接回到原畫面查證
        const url = `${location.origin}${location.pathname}${location.hash}`;
        return [c.subject, c.season, note, when ? (c.isHistory ? when : `截至 ${when}`) : null,
            `${label}${en ? `（${en}）` : ''} ${value}${unit}${rank ? `（聯盟第${rank.rank}）` : ''}`, `資料：${g.src || 'NBA.com Stats'}`, url].filter(Boolean).join('｜');
    };
    const doCopy = async (text) => { const ok = await copyText(text); toast(ok ? `已複製：${text}` : '複製失敗，請手動選取'); };

    const CopyIcon = () => (
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true"><rect x="9" y="9" width="12" height="12" rx="1" /><path d="M5 15V5a2 2 0 0 1 2-2h10" /></svg>
    );
    // 複製鈕：桌面滑過格子才出現、觸控裝置常駐；stopPropagation 避免觸發外層「開走勢」
    const CopyBtn = ({ text, className = '' }) => (
        <button type="button" aria-label="複製引用" title="複製引用"
            onClick={(e) => { e.stopPropagation(); doCopy(typeof text === 'function' ? text() : text); }}
            className={`inline-flex h-6 w-6 items-center justify-center text-slate-500 hover:text-[#12A150] opacity-0 group-hover/cell:opacity-100 focus:opacity-100 [@media(hover:none)]:opacity-100 ${className}`}>
            <CopyIcon />
        </button>
    );

    // 指標定義「?」：點開小卡（定義／計算／來源），點外面或 Esc 關閉
    // cite：給了就在小卡底部放「複製引用」（每格只留一個圖示，取代獨立的 CopyBtn）；
    //       該指標沒有 glossary 定義時退回單獨的 CopyBtn，引用功能不會消失
    // rank：{ rank, n, date }，有給就在小卡加一行名次說明
    // quote：回傳引用籃項目的函式（window.Quote.make 組），有給就在「複製引用」旁放「加入引用籃」；
    //        沒有 glossary 定義也照樣開小卡（只放按鈕），不讓加入引用籃的入口消失
    const Info = ({ k, align = 'left', cite, rank, quote }) => {
        const g = (window.GLOSSARY || {})[k];
        const [open, setOpen] = React.useState(false);
        const [pos, setPos] = React.useState(null);
        const ref = React.useRef(null), popRef = React.useRef(null);
        React.useEffect(() => {
            if (!open) return;
            const off = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
            const esc = (e) => { if (e.key === 'Escape') { e.stopPropagation(); setOpen(false); } };
            document.addEventListener('mousedown', off); document.addEventListener('keydown', esc, true);
            return () => { document.removeEventListener('mousedown', off); document.removeEventListener('keydown', esc, true); };
        }, [open]);
        // 小卡用 fixed 定位、夾在視窗內：absolute 往單側展開時，手機上靠邊的「?」會讓小卡超出畫面，
        // 放在可橫捲表格（overflow-x-auto）表頭裡的還會被容器裁掉。捲動／縮放時跟著按鈕重算
        React.useLayoutEffect(() => {
            if (!open) { setPos(null); return; }
            const place = () => {
                const b = ref.current && ref.current.getBoundingClientRect(), p = popRef.current;
                if (!b || !p) return;
                const W = document.documentElement.clientWidth, H = window.innerHeight, M = 8, w = p.offsetWidth, h = p.offsetHeight;
                const left = Math.max(M, Math.min(align === 'right' ? b.right - w : b.left, W - w - M));
                const below = b.bottom + 4;
                const top = below + h > H - M && b.top - 4 - h >= M ? b.top - 4 - h : below;
                setPos({ left, top });
            };
            place();
            window.addEventListener('scroll', place, true); window.addEventListener('resize', place);
            return () => { window.removeEventListener('scroll', place, true); window.removeEventListener('resize', place); };
        }, [open, align]);
        if (!g && !quote) return cite ? <CopyBtn text={cite} /> : null;
        const addQuote = () => {
            const r = window.Quote.add(typeof quote === 'function' ? quote() : quote);
            toast(r.added ? `已加入引用籃（${r.total} 項）` : `引用籃裡已經有這一項（${r.total} 項）`);
        };
        const btnCls = 'inline-flex min-h-[24px] items-center gap-1.5 border border-white/15 px-2.5 text-[11px] text-slate-300 hover:border-[#12A150] hover:text-[#12A150]';
        return (
            <span ref={ref} className="relative inline-flex align-middle">
                {/* 按鈕本身 24px（觸控目標下限，檢測工具量的是按鈕框），上下負邊距抵銷多出的高度；圓圈仍是 16px。
                    左右不可用負邊距：會吃進相鄰的複製鈕／排序鈕，造成點擊範圍重疊 */}
                <button type="button" aria-label="指標定義" title={cite || quote ? '指標定義／複製引用' : undefined} aria-expanded={open} onClick={(e) => { e.stopPropagation(); setOpen(o => !o); }}
                    className="group/info -my-1 inline-flex h-6 w-6 items-center justify-center">
                    <span aria-hidden="true" className={`inline-flex h-4 w-4 items-center justify-center rounded-full border text-[9px] leading-none ${open ? 'border-[#12A150] text-[#12A150]' : 'border-white/20 text-slate-500 group-hover/info:border-white/40 group-hover/info:text-slate-200'}`}>?</span>
                </button>
                {open && (
                    <span ref={popRef} role={cite || quote ? 'dialog' : 'tooltip'} aria-label={cite || quote ? '指標定義' : undefined} onClick={(e) => e.stopPropagation()}
                        style={pos ? { left: pos.left, top: pos.top } : { left: 0, top: 0, visibility: 'hidden' }}
                        className="fixed z-40 block w-72 max-w-[calc(100vw-16px)] border border-white/15 bg-[#0C1A2E] p-3 text-left text-[12px] font-normal normal-case leading-relaxed tracking-normal text-slate-200 shadow-2xl whitespace-normal">
                        {g ? (<>
                            <span className="block">{g.def}</span>
                            {g.calc && <span className="mt-1.5 block font-mono text-[11px] text-slate-400">計算：{g.calc}</span>}
                            <span className="mt-1.5 block text-[11px] text-slate-500">來源：{g.src}</span>
                            {g.verify && <span className="mt-1.5 block text-[11px] text-amber-300/90">此定義的細節待確認</span>}
                        </>) : <span className="block text-slate-400">這個指標還沒有定義說明。</span>}
                        {rank && (
                            <span className="mt-1.5 block text-[11px] text-slate-400">
                                聯盟第 {rank.rank}（{rank.n} 隊）：依 NBA 官方全季數值排序{rank.date ? `，快照 ${rank.date}` : ''}；與逐場重算的數字可能差一點小數，同值同名次
                            </span>
                        )}
                        {(cite || quote) && (
                            <span className="mt-2.5 flex flex-wrap gap-2">
                                {cite && (
                                    <button type="button" onClick={(e) => { e.stopPropagation(); setOpen(false); doCopy(typeof cite === 'function' ? cite() : cite); }} className={btnCls}>
                                        <CopyIcon />複製引用
                                    </button>
                                )}
                                {quote && (
                                    <button type="button" onClick={(e) => { e.stopPropagation(); setOpen(false); addQuote(); }} className={btnCls}>
                                        <span aria-hidden="true">＋</span>加入引用籃
                                    </button>
                                )}
                            </span>
                        )}
                    </span>
                )}
            </span>
        );
    };

    // gkey：glossary 的 key（顯示「?」定義）；citeAsOf：'snap' 快照日 / 'agg' 截至日 / 'none'；citeNote：期間或場次等補充；
    // valueTitle：滑鼠移上去顯示的完整數值（例如縮寫金額的完整金額）
    // ── 匯出：CSV 與 PNG 專欄配圖 ──
    const slug = (s) => String(s || '').replace(/[\\/:*?"<>|\s]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
    const fileName = (title, ext) => {
        const c = window.CiteCtx || {};
        const when = c.isHistory ? '期末' : (c.asOfSnap || '');
        return ['wolves-ledger', slug(c.subject), slug(c.season), slug(title), slug(when)].filter(Boolean).join('_') + '.' + ext;
    };
    const download = (href, name) => {
        const a = document.createElement('a'); a.href = href; a.download = name;
        document.body.appendChild(a); a.click();
        setTimeout(() => { if (href.startsWith('blob:')) URL.revokeObjectURL(href); a.remove(); }, 1500);
    };
    // source：資料來源說明（預設 NBA.com；薪資頁等非 NBA.com 資料要傳自己的來源）
    const DEFAULT_SOURCE = '資料：NBA.com Stats／Synergy';
    const provenance = (title, source) => {
        const c = window.CiteCtx || {};
        return [`Wolves Ledger`, title, c.subject, c.season, c.isHistory ? '期末快照' : (c.asOfSnap ? `截至 ${c.asOfSnap}` : null), source || DEFAULT_SOURCE]
            .filter(Boolean).join('｜');
    };
    // CSV：第一列為出處說明，空一列後才是表頭；加 UTF-8 BOM 讓 Excel 正確顯示中文
    const exportCSV = ({ title, header, rows, source }) => {
        const esc = (v) => { const s = v == null ? '' : String(v); return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
        const lines = [[provenance(title, source)], [], header, ...rows].map(r => r.map(esc).join(','));
        const blob = new Blob(['﻿' + lines.join('\r\n')], { type: 'text/csv;charset=utf-8' });
        download(URL.createObjectURL(blob), fileName(title, 'csv'));
        toast(`已匯出 CSV：${title}`);
    };

    // PNG：html-to-image 只在第一次匯出時才載入（鎖定版本），平常不影響載入速度
    const H2I_SRC = 'https://cdn.jsdelivr.net/npm/html-to-image@1.11.13/dist/html-to-image.js';
    let h2iPromise = null;
    const loadH2I = () => {
        if (window.htmlToImage) return Promise.resolve();
        if (!h2iPromise) h2iPromise = new Promise((res, rej) => {
            const s = document.createElement('script'); s.src = H2I_SRC; s.onload = res;
            s.onerror = () => { h2iPromise = null; rej(new Error('圖片匯出模組載入失敗')); };
            document.head.appendChild(s);
        });
        return h2iPromise;
    };
    // 把目標節點複製到固定尺寸的配圖版面（字標＋標題＋圖＋出處），等比縮放置中後輸出 PNG。
    // 不放 NBA Logo／頭像：跨網域圖片會讓畫布無法輸出，也避免在配圖上使用官方商標
    const exportPNG = async (node, { title, ratio = '16:9', source }) => {
        if (!node) return;
        const [W, H] = ratio === '1:1' ? [1080, 1080] : [1600, 900];
        const c = window.CiteCtx || {};
        toast('正在產生圖片…');
        try {
            await loadH2I();
            // 外層 holder 負責藏到畫面外；frame 本身只用一般定位——html-to-image 會把根節點的計算後樣式一起複製，
            // 若 frame 自己是 position:fixed + 負座標，內容會被畫到圖片外，輸出整張空白（實測踩過）
            const holder = document.createElement('div');
            holder.style.cssText = 'position:fixed;left:-30000px;top:0;pointer-events:none;';
            const frame = document.createElement('div');
            frame.style.cssText = `position:relative;width:${W}px;height:${H}px;box-sizing:border-box;padding:52px 60px 40px;display:flex;flex-direction:column;background:#0A1626;color:#F8FAFC;font-family:'Noto Sans TC',system-ui,sans-serif;`;
            holder.appendChild(frame);
            const when = c.isHistory ? '期末快照' : (c.asOfSnap ? `截至 ${c.asOfSnap}` : '');
            frame.innerHTML = `
                <div style="display:flex;align-items:flex-end;justify-content:space-between;gap:24px;border-bottom:1px solid rgba(255,255,255,.15);padding-bottom:18px;">
                    <div style="min-width:0;">
                        <div style="font-family:'Barlow Condensed','Noto Sans TC',sans-serif;font-weight:700;font-size:${ratio === '1:1' ? 46 : 52}px;line-height:1.05;letter-spacing:.01em;"></div>
                        <div style="margin-top:8px;font-size:20px;color:#C4CED2;"></div>
                    </div>
                    <div style="flex:none;font-family:'Barlow Condensed',sans-serif;font-weight:700;font-size:26px;letter-spacing:.06em;text-transform:uppercase;">WOLVES <span style="color:#12A150;">LEDGER</span></div>
                </div>
                <div data-body style="position:relative;flex:1;min-height:0;margin-top:28px;"></div>
                <div style="display:flex;justify-content:space-between;gap:24px;margin-top:20px;border-top:1px solid rgba(255,255,255,.1);padding-top:14px;font-family:'JetBrains Mono',monospace;font-size:15px;color:#8A99A8;">
                    <span>資料：NBA.com Stats／Synergy</span><span></span>
                </div>`;
            // 文字一律用 textContent 寫入（標題含球員名等資料，不可當 HTML 解析）
            frame.children[0].children[0].children[0].textContent = title;
            frame.children[0].children[0].children[1].textContent = [c.subject, c.season, when].filter(Boolean).join('　·　');
            frame.children[2].children[0].textContent = source || DEFAULT_SOURCE;
            frame.children[2].children[1].textContent = `${location.host}${location.pathname}`;
            const body = frame.querySelector('[data-body]');
            const clone = node.cloneNode(true);
            clone.querySelectorAll('[aria-label="複製引用"],[aria-label="指標定義"],[data-export-hide]').forEach(el => el.remove());
            clone.style.width = node.offsetWidth + 'px';
            clone.style.position = 'absolute'; clone.style.left = '0'; clone.style.top = '0';
            clone.style.transformOrigin = 'top left';
            body.appendChild(clone);
            document.body.appendChild(holder);
            const bw = body.clientWidth, bh = body.clientHeight;
            const cw = clone.scrollWidth, ch = clone.scrollHeight;
            const k = Math.min(bw / cw, bh / ch, 2.2);
            clone.style.transform = `scale(${k})`;
            clone.style.left = Math.max(0, (bw - cw * k) / 2) + 'px';
            clone.style.top = Math.max(0, (bh - ch * k) / 2) + 'px';
            if (document.fonts && document.fonts.ready) await document.fonts.ready;
            const url = await window.htmlToImage.toPng(frame, { width: W, height: H, pixelRatio: 1, backgroundColor: '#0A1626' });
            holder.remove();
            download(url, fileName(title, 'png').replace('.png', `_${ratio.replace(':', 'x')}.png`));
            toast(`已匯出圖片（${ratio}）：${title}`);
        } catch (e) {
            console.error('export png failed', e);
            toast(`圖片匯出失敗：${e.message || e}`);
            document.querySelectorAll('body > div[style*="-30000px"]').forEach(el => el.remove());
        }
    };

    // 匯出選單：CSV（有 csv 時）＋ PNG 16:9 / 1:1 ＋ 純文字（有 text 時，貼臉書等不吃表格的地方）。
    // getNode 回傳要輸出成圖的 DOM 節點；text() 回傳字串，回 null 表示呼叫端自己處理（例如資料未載完）
    const ExportMenu = ({ title, getNode, csv, text, source }) => {
        const [open, setOpen] = React.useState(false);
        const ref = React.useRef(null);
        React.useEffect(() => {
            if (!open) return;
            const off = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
            document.addEventListener('mousedown', off);
            return () => document.removeEventListener('mousedown', off);
        }, [open]);
        const item = 'block w-full px-3 py-2 text-left text-[12px] text-slate-200 hover:bg-white/[0.06]';
        return (
            <span ref={ref} className="relative inline-flex" data-export-hide>
                <button type="button" aria-haspopup="menu" aria-expanded={open} onClick={() => setOpen(o => !o)}
                    className="rounded-full border border-white/15 px-3 py-1 text-xs text-slate-400 hover:border-white/30 hover:text-slate-100">匯出 ▾</button>
                {open && (
                    <span role="menu" className="absolute right-0 top-8 z-40 block w-44 border border-white/15 bg-[#0C1A2E] py-1 shadow-2xl">
                        {getNode && <button type="button" role="menuitem" className={item} onClick={() => { setOpen(false); exportPNG(getNode(), { title, ratio: '16:9', source }); }}>配圖 PNG · 16:9</button>}
                        {getNode && <button type="button" role="menuitem" className={item} onClick={() => { setOpen(false); exportPNG(getNode(), { title, ratio: '1:1', source }); }}>配圖 PNG · 1:1</button>}
                        {csv && <button type="button" role="menuitem" className={item} onClick={() => { setOpen(false); exportCSV({ title, source, ...csv() }); }}>表格 CSV（Excel）</button>}
                        {text && <button type="button" role="menuitem" className={item} onClick={async () => {
                            setOpen(false);
                            const t = text(); if (t == null) return;
                            toast(await copyText(t) ? `已複製純文字：${title}（可直接貼到臉書）` : '複製失敗，請改用 CSV 匯出');
                        }}>複製純文字（臉書）</button>}
                    </span>
                )}
            </span>
        );
    };

    // rank：window.leagueRank 回傳的 { rank, n, date }（只在全隊當季快照格），有給就在數值下方加「聯盟第N」
    // neutral：次數類（觸球、切入次數等），引用籃的 📈📉 不判好壞
    // quote：覆寫引用籃項目的欄位（例：Splits 期間比較改成 { kind: 'compare', values: [全季, 此期間] }）；null＝不提供加入引用籃
    const StatCell = ({ label, en, value, unit = '', prevValue, betterIsLarger = true, naReason = null, pct = null, pctLabel, gkey, citeAsOf = 'snap', citeNote, valueTitle, rank = null, neutral = false, quote }) => {
        const isNA = naReason && isBlank(value);
        const missing = isBlank(value);
        if (missing) rank = null;
        const quoteFn = missing || quote === null ? undefined : () => window.Quote.make(Object.assign({
            label, en, gkey, values: [{ value, unit }], rank: rank ? { rank: rank.rank, n: rank.n } : null,
            better: neutral ? null : (betterIsLarger ? 'high' : 'low'), asOf: citeAsOf,
        }, quote || {}));
        return (
            <div className="group/cell relative border-r border-b border-white/[0.08] px-3 pt-2.5 pb-3 min-w-0">
                {/* 有 gkey：複製引用收進「?」小卡；沒有 gkey 才放右上角獨立複製鈕 */}
                {!gkey && !missing && (
                    <CopyBtn className="absolute right-1 top-1"
                        text={() => citeLine({ label, en, value, unit, gkey, asOf: citeAsOf, note: citeNote, rank })} />
                )}
                {/* pr-8：右上角複製鈕佔 4–28px，標題要留到 32px 外，兩個點擊範圍才不重疊 */}
                <div className={`flex items-center text-[11px] leading-tight text-slate-300 min-w-0 ${gkey ? '' : 'pr-8'}`}>
                    {/* 手機 3 欄時每格只剩約 60px：標籤換行而不截斷（「急停三分命中率」會被切成「急停三分…」） */}
                    <span className="min-w-0 break-words">{label}</span>
                    {gkey && <Info k={gkey} rank={rank} quote={quoteFn} cite={missing ? undefined : () => citeLine({ label, en, value, unit, gkey, asOf: citeAsOf, note: citeNote, rank })} />}
                </div>
                {en && <div className="font-mono text-[10px] leading-tight text-slate-500 break-words">{en}</div>}
                <div className="mt-2 flex items-baseline gap-1.5 min-w-0">
                    {isNA ? (
                        <span className="font-display text-[26px] font-semibold leading-none text-slate-600 cursor-help" title={naReason}>—</span>
                    ) : missing ? (
                        <span className="font-display text-[26px] font-semibold leading-none text-slate-600" title="此項無資料">—</span>
                    ) : (
                        <span title={valueTitle} className={`font-display text-[26px] font-semibold leading-none tabular-nums text-slate-50 ${valueTitle ? 'cursor-help' : ''}`}>
                            {value}{unit && <span className="ml-0.5 text-[15px] font-medium text-slate-400">{unit}</span>}
                        </span>
                    )}
                    {!isNA && !missing && <span className="ml-auto"><Delta value={value} prevValue={prevValue} unit={unit} betterIsLarger={betterIsLarger} /></span>}
                </div>
                {rank && <div className="mt-1.5 font-mono text-[11px] tabular-nums text-slate-400">聯盟第{rank.rank}</div>}
                {pct != null && <PctBar value={pct} label={pctLabel} />}
            </div>
        );
    };

    // cols：完整的 grid-cols class（例 'grid-cols-2 sm:grid-cols-4'），由呼叫端依指標數決定
    const Ledger = ({ cols = 'grid-cols-2 sm:grid-cols-4', children }) => (
        <div className={`grid ${cols} border-t border-l border-white/[0.08]`}>{children}</div>
    );
    // 依指標數挑欄數：桌面選能整除的欄數（每列排滿、不留空格），手機一律 2 欄（3 個時 3 欄）
    const ledgerCols = (n) => n <= 2 ? 'grid-cols-2'
        : n === 3 ? 'grid-cols-3'
        : n % 5 === 0 ? 'grid-cols-2 sm:grid-cols-5'          // 5、10
        : n % 4 === 0 ? 'grid-cols-2 sm:grid-cols-4'          // 4、8、12
        : n % 6 === 0 ? 'grid-cols-2 sm:grid-cols-3 lg:grid-cols-6'
        : n % 3 === 0 ? 'grid-cols-2 sm:grid-cols-3'          // 9
        : 'grid-cols-2 sm:grid-cols-4';

    // columns: [{ key, label, en, align:'left'|'right', render(row), sortValue(row), cellClass(row) }]
    // exportTitle：給了就在表格右上加「匯出」（PNG 配圖＋CSV）；CSV 值取 c.csv(r)，否則取 r[c.key] 原始值
    const DataTable = ({ columns, rows, initialSort = null, rowKey = (r, i) => i, caption, exportTitle }) => {
        const [sort, setSort] = React.useState(initialSort);   // { key, dir: 'asc'|'desc' }
        const wrapRef = React.useRef(null);
        const colOf = (k) => columns.find(c => c.key === k);
        const sorted = React.useMemo(() => {
            if (!sort) return rows;
            const c = colOf(sort.key); if (!c) return rows;
            const get = c.sortValue || (r => r[c.key]);
            const sign = sort.dir === 'asc' ? 1 : -1;
            return rows.slice().sort((a, b) => {
                const x = get(a), y = get(b);
                if (isBlank(x) && isBlank(y)) return 0;
                if (isBlank(x)) return 1;            // 無資料一律排最後
                if (isBlank(y)) return -1;
                return (typeof x === 'number' && typeof y === 'number' ? x - y : String(x).localeCompare(String(y))) * sign;
            });
        }, [rows, sort]);
        const toggle = (k) => setSort(s => (s && s.key === k)
            ? { key: k, dir: s.dir === 'desc' ? 'asc' : 'desc' }
            : { key: k, dir: colOf(k).align === 'left' ? 'asc' : 'desc' });
        const csv = () => ({
            header: columns.map(c => c.en ? `${c.label} ${c.en}` : c.label),
            rows: sorted.map(r => columns.map(c => c.csv ? c.csv(r) : (typeof r[c.key] === 'number' || typeof r[c.key] === 'string' ? r[c.key] : ''))),
        });
        return (
            <div>
            {exportTitle && (
                <div className="mb-2 flex justify-end"><ExportMenu title={exportTitle} getNode={() => wrapRef.current} csv={csv} /></div>
            )}
            <div ref={wrapRef} className="overflow-x-auto border-t border-white/[0.08]">
                <table className="w-full text-sm border-collapse">
                    {caption && <caption className="sr-only">{caption}</caption>}
                    <thead>
                        <tr className="border-b border-white/15">
                            {columns.map((c, ci) => {
                                const active = sort && sort.key === c.key;
                                return (
                                    <th key={c.key} scope="col"
                                        aria-sort={active ? (sort.dir === 'asc' ? 'ascending' : 'descending') : 'none'}
                                        className={`px-3 py-2 font-normal whitespace-nowrap align-bottom ${c.align === 'left' ? 'text-left' : 'text-right'} ${ci === 0 ? 'max-sm:sticky max-sm:left-0 max-sm:z-[1] max-sm:bg-[#0A1626]' : ''}`}>
                                        <span className={`inline-flex items-start gap-0.5 ${c.align === 'left' ? '' : 'flex-row-reverse'}`}>
                                            <button onClick={() => toggle(c.key)}
                                                className={`inline-flex min-h-[24px] min-w-[24px] flex-col ${c.align === 'left' ? 'items-start' : 'items-end'} gap-0.5 hover:text-slate-100 ${active ? 'text-slate-100' : 'text-slate-400'}`}>
                                                <span className="text-[11px]">{c.label}{active && <span className="ml-1 text-[#12A150]">{sort.dir === 'asc' ? '↑' : '↓'}</span>}</span>
                                                {c.en && <span className="font-mono text-[10px] text-slate-500">{c.en}</span>}
                                            </button>
                                            {c.gkey && <Info k={c.gkey} align={ci === columns.length - 1 ? 'right' : 'left'} />}
                                        </span>
                                    </th>
                                );
                            })}
                        </tr>
                    </thead>
                    <tbody>
                        {sorted.map((r, i) => (
                            <tr key={rowKey(r, i)} className="border-b border-white/[0.06] odd:bg-white/[0.015] hover:bg-white/[0.04]">
                                {columns.map((c, ci) => (
                                    <td key={c.key}
                                        className={`px-3 py-2 whitespace-nowrap ${c.align === 'left' ? 'text-left text-slate-200' : 'text-right font-mono tabular-nums text-slate-200'} ${ci === 0 ? 'max-sm:sticky max-sm:left-0 max-sm:bg-[#0A1626] max-sm:whitespace-normal max-sm:min-w-[7.5rem] max-sm:max-w-[9.5rem] max-sm:text-[13px] max-sm:leading-snug' : ''} ${c.cellClass ? c.cellClass(r) : ''}`}>
                                        {c.render ? c.render(r) : (isBlank(r[c.key]) ? '—' : r[c.key])}
                                        {c.after && <span className="ml-1 inline-flex items-center align-middle">{c.after(r)}</span>}
                                    </td>
                                ))}
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
            </div>
        );
    };

    // 膠囊分段切換。options: [{ value, label, icon?, activeClass? }]；activeClass 讓攻（綠）/守（紅）各自上色
    const Seg = ({ options, value, onChange, ariaLabel, size = 'md' }) => (
        <div role="group" aria-label={ariaLabel} className="inline-flex shrink-0 rounded-full border border-white/15 p-[3px]">
            {options.map(o => {
                const on = o.value === value;
                return (
                    <button key={o.value} type="button" aria-pressed={on} onClick={() => onChange(o.value)}
                        disabled={!!o.disabled} title={o.title}
                        className={`inline-flex items-center gap-1.5 rounded-full whitespace-nowrap transition-colors ${size === 'sm' ? 'px-3 py-1 text-xs' : 'px-3.5 py-1.5 text-[13px]'} ${on ? (o.activeClass || 'bg-[#C4CED2] text-[#0A1626] font-medium') : o.disabled ? 'cursor-not-allowed text-slate-600' : 'text-slate-400 hover:text-slate-100'}`}>
                        {o.icon}{o.label}
                    </button>
                );
            })}
        </div>
    );

    // 分頁列（捲動時固定在頂端）：主畫面章節列、薪資頁、單場頁共用。tabs: [{ key, label }]
    // numbered：分頁前標 01 02…（＝數字快捷鍵，手機無鍵盤隱藏）；right：右側附加控制項（攻守切換、賽季選單）
    // bleed：放在 <main> 內時用負邊距撐滿版寬；不帶時自己置中（章節列在 main 外）
    const TabBar = ({ tabs, value, onChange, ariaLabel, right, numbered, bleed, className = '' }) => {
        // 手機上分頁放不下時：右緣漸層＋「›」按鈕提示還有分頁（例：主畫面章節列只露出前四章，Playtype／跨季要往右滑）
        const scroller = React.useRef(null);
        const [more, setMore] = React.useState(false);
        React.useEffect(() => {
            const el = scroller.current; if (!el) return;
            const check = () => setMore(el.scrollLeft + el.clientWidth < el.scrollWidth - 4);
            check();
            el.addEventListener('scroll', check, { passive: true }); window.addEventListener('resize', check);
            return () => { el.removeEventListener('scroll', check); window.removeEventListener('resize', check); };
        }, [tabs.length]);
        // 選中的分頁捲進可視範圍（數字鍵或網址直接切到後面的章節時）
        React.useEffect(() => {
            const el = scroller.current; const on = el && el.querySelector('[aria-current="page"]');
            if (on && el.scrollWidth > el.clientWidth) on.scrollIntoView({ block: 'nearest', inline: 'nearest' });
        }, [value]);
        const row = (
            <div className="flex items-center gap-3">
                <div className="relative flex min-w-0 flex-1 items-center">
                <div ref={scroller} className={`flex min-w-0 flex-1 items-center overflow-x-auto [scrollbar-width:none] ${more ? '[mask-image:linear-gradient(to_right,#000_75%,transparent)]' : ''}`}>
                    {tabs.map((t, i) => {
                        const on = value === t.key;
                        return (
                            <button key={t.key} type="button" onClick={() => onChange(t.key)} aria-current={on ? 'page' : undefined}
                                title={numbered ? `快捷鍵 ${i + 1}` : undefined}
                                className={`flex shrink-0 items-baseline gap-1.5 border-b-2 px-2.5 sm:px-3 py-3 text-[14px] transition-colors ${on ? 'border-[#12A150] text-slate-50 font-medium' : 'border-transparent text-slate-400 hover:text-slate-100'}`}>
                                {numbered && <span className={`hidden sm:inline font-mono text-[10px] ${on ? 'text-[#12A150]' : 'text-slate-600'}`}>{String(i + 1).padStart(2, '0')}</span>}
                                {t.label}
                            </button>
                        );
                    })}
                </div>
                {more && (
                    <button type="button" aria-label="看更多分頁" onClick={() => scroller.current && scroller.current.scrollBy({ left: 120, behavior: 'smooth' })}
                        className="absolute right-0 top-1/2 flex h-7 w-7 -translate-y-1/2 items-center justify-center rounded-full border border-white/15 bg-[#0A1626] text-[15px] leading-none text-slate-300 hover:text-slate-50">›</button>
                )}
                </div>
                {right}
            </div>
        );
        return bleed ? (
            <nav aria-label={ariaLabel} className={`sticky top-0 z-20 -mx-4 border-b border-white/10 bg-[#0A1626]/85 px-4 backdrop-blur-md md:-mx-6 md:px-6 ${className}`}>{row}</nav>
        ) : (
            <nav aria-label={ariaLabel} className={`sticky top-0 z-20 border-b border-white/10 bg-[#0A1626]/85 backdrop-blur-md ${className}`}>
                <div className="max-w-7xl mx-auto px-4 md:px-6">{row}</div>
            </nav>
        );
    };
    // 數字鍵 1…N 切 TabBar 分頁（獨立整頁用；主畫面章節由 App 的全域 keydown 處理）。輸入框聚焦、按修飾鍵時不攔截
    // keys：分頁 key 陣列，或按鍵當下才取值的函式（分頁清單要等資料載入才知道、hook 又得在提早 return 之前呼叫時用）
    const useTabKeys = (keys, onChange) => {
        const ref = React.useRef();
        ref.current = { keys, onChange };
        React.useEffect(() => {
            const onKey = (e) => {
                const el = e.target || {};
                if (/^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName || '') || el.isContentEditable) return;
                if (e.metaKey || e.ctrlKey || e.altKey) return;
                const { keys: k, onChange: fn } = ref.current;
                const n = parseInt(e.key, 10), ks = typeof k === 'function' ? k() : k;
                if (n >= 1 && n <= ks.length) fn(ks[n - 1]);
            };
            window.addEventListener('keydown', onKey);
            return () => window.removeEventListener('keydown', onKey);
        }, []);
    };

    // 區塊：取代舊的「左色條大框」。accent 保留原本色條語意（攻綠/守紅/Clutch 琥珀/結構藍），縮成標題前的小色標
    const ACCENT = { green: 'bg-[#12A150]', red: 'bg-[#EF4444]', blue: 'bg-[#236192]', amber: 'bg-amber-400', silver: 'bg-[#C4CED2]' };
    const Section = ({ title, en, sub, right, accent, children, className = '' }) => (
        <section className={className}>
            <header className="mb-4 flex flex-wrap items-end justify-between gap-x-4 gap-y-2 border-b border-white/15 pb-2.5">
                <div className="min-w-0">
                    <h2 className="flex items-baseline gap-2 text-[20px] font-bold leading-tight text-slate-50">
                        {accent && <span className={`inline-block h-3.5 w-1 shrink-0 ${ACCENT[accent] || ACCENT.silver}`} aria-hidden="true"></span>}
                        <span>{title}</span>
                        {en && <span className="font-mono text-[11px] font-normal text-slate-500">{en}</span>}
                    </h2>
                    {sub && <p className="mt-1 text-[12px] leading-relaxed text-slate-400">{sub}</p>}
                </div>
                {/* max-w-full：右側操作比手機版寬還長時在自己框內換行，不把整頁撐出橫向捲動 */}
                {right && <div className="flex max-w-full shrink-0 flex-wrap items-center gap-2">{right}</div>}
            </header>
            {children}
        </section>
    );
    // 空狀態／提示（取代各處 bg-slate-800/50 圓角提示框）
    const Note = ({ children, tone = 'muted' }) => (
        <div className={`border px-4 py-3 text-sm ${tone === 'warn' ? 'border-amber-500/30 bg-amber-500/[0.06] text-amber-200' : 'border-white/10 bg-white/[0.02] text-slate-400'}`}>{children}</div>
    );

    // 篩選膠囊（期間篩選列等）與同風格下拉
    const Chip = ({ active, onClick, children, title }) => (
        <button type="button" aria-pressed={!!active} onClick={onClick} title={title}
            className={`shrink-0 rounded-full border px-3 py-1 text-xs whitespace-nowrap transition-colors ${active ? 'border-[#12A150] bg-[#12A150]/10 text-slate-50' : 'border-white/15 text-slate-400 hover:border-white/30 hover:text-slate-100'}`}>
            {children}
        </button>
    );
    const selectClass = (active) => `shrink-0 rounded-full border bg-[#0A1626] px-3 py-1 text-xs focus:outline-none focus:border-[#12A150] ${active ? 'border-[#12A150] text-slate-50' : 'border-white/15 text-slate-400'}`;

    // 可橫捲表格裡的展開列（td colSpan）：內容寬度會跟著整張表攤開，手機上數值落到畫面外。
    // 改成黏在捲動容器左緣、寬度＝可視寬度（容器變寬時跟著量）
    const ExpandRow = ({ colSpan, className = '', children }) => {
        const ref = React.useRef(null);
        const [w, setW] = React.useState(null);
        React.useLayoutEffect(() => {
            let sc = ref.current && ref.current.parentElement;
            while (sc && !/(auto|scroll)/.test(getComputedStyle(sc).overflowX)) sc = sc.parentElement;
            if (!sc) return;
            const update = () => setW(sc.clientWidth);
            update();
            if (!window.ResizeObserver) return;
            const ro = new ResizeObserver(update);
            ro.observe(sc);
            return () => ro.disconnect();
        }, []);
        return (
            <tr><td colSpan={colSpan} className={`p-0 ${className}`}>
                <div ref={ref} className="sticky left-0" style={w ? { width: w } : undefined}>{children}</div>
            </td></tr>
        );
    };

    return { splitTitle, pctColor, Delta, PctBar, StatCell, Ledger, ledgerCols, DataTable, Seg, TabBar, useTabKeys, Section, Note, Chip, selectClass, ExpandRow, copyText, toast, citeLine, doCopy, CopyBtn, Info, exportCSV, exportPNG, ExportMenu };
})();


// ---------- quoteFormat.js ----------
// 引用籃資料層＋貼文排版：window.Quote（不含 JSX，可在 Node 單獨測 Quote.render）
// 各頁從「?」小卡「加入引用籃」→ 存在 localStorage（wt_quote_v1，保留到手動清空）→ QuoteBasket 抽屜排序／合併 → render 成貼文用純文字
// 項目：{ id, kind: 'single'|'compare', subject, context, label, en, gkey, values: [{ tag, value, unit }], sep: '→'|'vs.',
//        rank: { rank, n }|null, pr: 百分位|null（Playtype）, better: 'high'|'low'|null, asOf, url }
//   合併後的項目：{ id, kind, subject, context, sep, parts: [項目A, 項目B] }（成對指標寫成一行「A／B」）
// 排版規則（使用者確認的格式）：「：」分隔名稱與數值、「／」成對指標、「→」時間先後、「vs.」並列
//   單值 1A：●主體｜情境（括號為聯盟排名）＋ ※指標：值（第8）
//   前後 2A：●主體｜情境：A → B ＋ ※指標：x → y（2B 差值、2C 加 📈📉 為選項）
//   並列 3A：（以下為 主體｜情境，A vs. B）＋ ※指標：x vs. y；三個以上值 3C：●主體｜指標 ＋ 每個對象一行
(function () {
    const KEY = 'wt_quote_v1';
    const OPTS_KEY = 'wt_quote_opts_v1';
    const EVENT = 'wt-quote-change';

    // 成對指標合併成一行時的名稱（順序不拘）；沒列到的組合寫成「A／B」
    const PAIRS = [
        ['FGA', 'FG_PCT', '出手數／命中率'],
        ['FG3A', 'FG3_PCT', '三分出手數／命中率'],
        ['FTA', 'FT_PCT', '罰球出手數／命中率'],
        ['DRIVES', 'DRIVE_FG_PCT', '切入次數／命中率'],
        ['CATCH_SHOOT_FGA', 'CATCH_SHOOT_EFG_PCT', '接球跳投出手數／有效命中率'],
        ['CATCH_SHOOT_FGA', 'CATCH_SHOOT_FG3_PCT', '接球跳投出手數／三分命中率'],
        ['PULL_UP_FGA', 'PULL_UP_EFG_PCT', '急停跳投出手數／有效命中率'],
        ['PULL_UP_FGA', 'PULL_UP_FG3_PCT', '急停跳投出手數／三分命中率'],
        ['SCREEN_ASSISTS', 'SCREEN_AST_PTS', '掩護助攻次數／得分'],
        ['D_FGA', 'D_FG_PCT', '防守出手數／對手命中率'],
        ['REB_CHANCES', 'REB_COL_PCT', '籃板機會／轉換率'],
    ];
    const DEFAULT_OPTS = {
        header: 'none',      // 整段標頭：none／key（●關鍵數據：）／custom（headerText）
        headerText: '',
        prefix: '※',         // 行首：※／•／''
        names: 'zh',         // 指標名稱：zh／en／both（中文（原文））
        rank: true,          // 帶名次
        ptStyle: 'league',   // Playtype 名次寫法：league（第11）／pr（PR66）
        cmpStyle: 'arrow',   // 前後比較：arrow（2A）／delta（2B 差值）／trend（2C 加 📈📉）
        asOfNote: false,     // 文末「※本文數據統計至 M/D」
        source: false,       // 文末附資料來源＋網址
    };

    // ── 排版（純函式）──
    const render = (items, opts) => {
        const o = Object.assign({}, DEFAULT_OPTS, opts || {});
        const P = o.prefix || '';
        const nm = (it) => o.names === 'en' ? (it.en || it.label)
            : (o.names === 'both' && it.en && it.en !== it.label) ? `${it.label}（${it.en}）` : it.label;
        const pairName = (a, b) => {
            const hit = PAIRS.find(([x, y]) => (x === a.gkey && y === b.gkey) || (x === b.gkey && y === a.gkey));
            if (hit && o.names !== 'en') return hit[0] === a.gkey ? hit[2] : `${nm(a)}／${nm(b)}`;
            return `${nm(a)}／${nm(b)}`;
        };
        const nameOf = (it) => it.parts ? pairName(it.parts[0], it.parts[1]) : nm(it);
        // Playtype：選 PR 寫法，或沒有名次（球員百分位不能換算名次）時寫 PR
        const usesPr = (it) => typeof it.pr === 'number' && (o.ptStyle === 'pr' || !it.rank);
        const rk = (it) => {
            if (!o.rank) return '';
            if (usesPr(it)) return `（PR${Math.round(it.pr)}）`;
            return it.rank ? `（第${it.rank.rank}）` : '';
        };
        const hasLeague = (it) => it.parts ? it.parts.some(hasLeague) : (!!it.rank && !usesPr(it));
        const val = (v) => v ? `${v.value}${v.unit || ''}` : '—';
        const num = (v) => { const n = parseFloat(String(v && v.value).replace(/[^\d.+-]/g, '')); return isNaN(n) ? null : n; };
        const decimals = (v) => { const m = String(v && v.value).match(/\.(\d+)/); return m ? m[1].length : 0; };
        const delta = (a, b) => {
            const x = num(a), y = num(b);
            if (x == null || y == null) return '—';
            const d = y - x, dec = Math.max(decimals(a), decimals(b));
            const s = d.toFixed(dec);
            return d > 0 ? `+${s}` : Number(s) === 0 ? (0).toFixed(dec) : s;
        };
        const trend = (it) => {
            if (it.parts || !it.better) return '';
            const x = num(it.values[0]), y = num(it.values[it.values.length - 1]);
            if (x == null || y == null || x === y) return '';
            return ((y > x) === (it.better === 'high')) ? ' 📈' : ' 📉';
        };
        const tagsOf = (it) => (it.parts ? it.parts[0] : it).values.map(v => v.tag || '');
        const valsAt = (it, i) => it.parts ? it.parts.map(p => val(p.values[i])).join('／') : val(it.values[i]);
        const ctxOf = (it) => it.context ? `｜${it.context}` : '';

        // 相鄰、同主體同情境同比較方式的項目合成一組；三個以上值的比較各自成組（3C）
        const groups = [];
        (items || []).forEach(it => {
            const n = tagsOf(it).length;
            const key = [it.kind, it.subject, it.context, it.kind === 'compare' ? `${it.sep}|${tagsOf(it).join('|')}` : ''].join('§');
            const last = groups[groups.length - 1];
            if (last && last.key === key && !(it.kind === 'compare' && n > 2)) last.items.push(it);
            else groups.push({ key, items: [it], wide: it.kind === 'compare' && n > 2 });
        });

        const blocks = groups.map(g => {
            const first = g.items[0];
            if (g.wide) {
                const tags = tagsOf(first);
                return [`●${first.subject}${ctxOf(first)}｜${nameOf(first)}`, ...tags.map((t, i) => `${t}：${valsAt(first, i)}`)];
            }
            if (first.kind === 'compare') {
                const [A, B] = tagsOf(first);
                if (first.sep === 'vs.') {
                    return [`（以下為 ${first.subject}${ctxOf(first)}，${A} vs. ${B}）`,
                        ...g.items.map(it => `${P}${nameOf(it)}：${valsAt(it, 0)} vs. ${valsAt(it, 1)}`)];
                }
                if (o.cmpStyle === 'delta') {
                    return [`●${first.subject}${ctxOf(first)}：${B}（括號為與${A}差距）`,
                        ...g.items.map(it => `${P}${nameOf(it)}：${it.parts
                            ? it.parts.map(p => `${val(p.values[1])}（${delta(p.values[0], p.values[1])}）`).join('／')
                            : `${val(it.values[1])}（${delta(it.values[0], it.values[1])}）`}`)];
                }
                return [`●${first.subject}${ctxOf(first)}：${A} → ${B}`,
                    ...g.items.map(it => `${P}${nameOf(it)}：${valsAt(it, 0)} → ${valsAt(it, 1)}${o.cmpStyle === 'trend' ? trend(it) : ''}`)];
            }
            const note = o.rank && g.items.some(hasLeague) ? '（括號為聯盟排名）' : '';
            return [`●${first.subject}${ctxOf(first)}${note}`,
                ...g.items.map(it => `${P}${nameOf(it)}：${it.parts
                    ? it.parts.map(p => `${val(p.values[0])}${rk(p)}`).join('／')
                    : `${val(it.values[0])}${rk(it)}`}`)];
        });

        const out = [];
        const head = o.header === 'key' ? '●關鍵數據：' : o.header === 'custom' ? String(o.headerText || '').trim() : '';
        if (head) out.push(head);
        blocks.forEach((b, i) => { if (i > 0 || head) out.push(''); out.push(...b); });
        const flat = [].concat(...(items || []).map(it => it.parts || [it]));
        const tail = [];
        if (o.asOfNote) {
            const d = flat.map(it => it.asOf).filter(x => /^\d{4}-\d{2}-\d{2}$/.test(x || '')).sort().pop();
            if (d) tail.push(`※本文數據統計至 ${Number(d.slice(5, 7))}/${Number(d.slice(8, 10))}`);
        }
        if (o.source) {
            tail.push('資料：NBA.com Stats');
            const url = flat.map(it => it.url).find(Boolean);
            if (url) tail.push(url);
        }
        if (tail.length && out.length) out.push('');
        return out.concat(tail).join('\n');
    };

    // ── 儲存（localStorage 不可用時退回記憶體，頁面照常運作）──
    let mem = [];
    let memOpts = null;
    const readJSON = (k, fallback) => {
        try { const s = window.localStorage.getItem(k); return s == null ? fallback : JSON.parse(s); } catch (e) { return fallback; }
    };
    const writeJSON = (k, v) => { try { window.localStorage.setItem(k, JSON.stringify(v)); } catch (e) { /* 私密模式等：只留在記憶體 */ } };
    const notify = () => { try { window.dispatchEvent(new CustomEvent(EVENT)); } catch (e) { /* Node 測試環境 */ } };
    const items = () => { const a = readJSON(KEY, mem); return Array.isArray(a) ? a : []; };
    const save = (a) => { mem = a; writeJSON(KEY, a); notify(); };
    const opts = () => Object.assign({}, DEFAULT_OPTS, readJSON(OPTS_KEY, memOpts) || {});
    const setOpts = (patch) => { memOpts = Object.assign(opts(), patch); writeJSON(OPTS_KEY, memOpts); notify(); };

    const sig = (it) => JSON.stringify([it.subject, it.context, it.label, (it.parts || [it]).map(p => p.values)]);
    const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
    // 回傳 { added, total }；同一主體／情境／指標／數值已在籃子裡就不重複加
    const add = (it) => {
        const a = items();
        if (a.some(x => sig(x) === sig(it))) return { added: false, total: a.length };
        a.push(Object.assign({ id: uid() }, it));
        save(a);
        return { added: true, total: a.length };
    };
    const remove = (id) => save(items().filter(x => x.id !== id));
    const move = (id, dir) => {
        const a = items(), i = a.findIndex(x => x.id === id), j = i + dir;
        if (i < 0 || j < 0 || j >= a.length) return;
        [a[i], a[j]] = [a[j], a[i]];
        save(a);
    };
    // 能否和下一項合併：都是未合併的同類項目、同主體同情境，比較項目還要比較對象相同
    const canMerge = (a, b) => !!(a && b && !a.parts && !b.parts && a.kind === b.kind && a.subject === b.subject
        && a.context === b.context && (a.kind !== 'compare'
            || (a.sep === b.sep && JSON.stringify(a.values.map(v => v.tag)) === JSON.stringify(b.values.map(v => v.tag)))));
    const merge = (id) => {
        const a = items(), i = a.findIndex(x => x.id === id);
        if (i < 0 || !canMerge(a[i], a[i + 1])) return;
        const [x, y] = [a[i], a[i + 1]];
        a.splice(i, 2, { id: uid(), kind: x.kind, subject: x.subject, context: x.context, sep: x.sep, parts: [x, y] });
        save(a);
    };
    const split = (id) => {
        const a = items(), i = a.findIndex(x => x.id === id);
        if (i < 0 || !a[i].parts) return;
        a.splice(i, 1, ...a[i].parts);
        save(a);
    };
    const clear = () => save([]);
    const subscribe = (fn) => {
        const onStorage = (e) => { if (!e.key || e.key === KEY || e.key === OPTS_KEY) fn(); };
        window.addEventListener(EVENT, fn);
        window.addEventListener('storage', onStorage);
        return () => { window.removeEventListener(EVENT, fn); window.removeEventListener('storage', onStorage); };
    };

    // 依目前畫面的引用情境（window.CiteCtx）組項目；fields 至少要有 label 與 values
    // asOf：'snap' 快照日／'agg' 截至日／'none'（同 UI.citeLine）
    const make = (fields) => {
        const c = window.CiteCtx || {};
        const subject = c.subject === 'Minnesota Timberwolves' ? '灰狼全隊' : (c.subject || '');
        const asOf = fields.asOf === 'none' || c.isHistory ? null : (fields.asOf === 'agg' ? c.asOfAgg : c.asOfSnap) || null;
        let url = '';
        try { url = `${window.location.origin}${window.location.pathname}${window.location.hash}`; } catch (e) { /* Node */ }
        const it = Object.assign({ kind: 'single', subject, context: c.context || c.season || '', sep: '→', rank: null, pr: null, better: null, url },
            fields, { asOf });
        // 原文只留名稱：畫面小字的補充說明（如「DIFF%（負=守得好）」）不進貼文
        if (it.en) it.en = String(it.en).replace(/（[^）]*）/g, '').trim();
        return it;
    };

    window.Quote = { render, items, add, remove, move, merge, split, canMerge, clear, opts, setOpts, subscribe, make, EVENT, DEFAULT_OPTS, PAIRS };
})();


// ---------- QuoteBasket.js ----------
// 引用籃：右下角浮動鈕（籃子有東西才出現）＋ 抽屜（桌面右側、手機全螢幕）
// 資料與排版在 quoteFormat.js（window.Quote）；各頁從「?」小卡「加入引用籃」放進來
const QuoteBasket = () => {
    const { useState, useEffect, useRef } = React;
    const Q = window.Quote;
    const UI = window.UI;
    const [items, setItems] = useState(() => Q.items());
    const [opts, setOptsState] = useState(() => Q.opts());
    const [open, setOpen] = useState(false);
    const [confirmClear, setConfirmClear] = useState(false);
    const panelRef = useRef(null);
    const fabRef = useRef(null);

    useEffect(() => Q.subscribe(() => { setItems(Q.items()); setOptsState(Q.opts()); }), []);
    // 開啟時焦點移進抽屜、Esc 關閉（capture：不讓頁面其他 Esc 處理先吃掉），關閉後焦點回到浮動鈕
    useEffect(() => {
        if (!open) return;
        if (panelRef.current) panelRef.current.focus();
        const esc = (e) => { if (e.key === 'Escape') { e.stopPropagation(); setOpen(false); } };
        document.addEventListener('keydown', esc, true);
        return () => { document.removeEventListener('keydown', esc, true); setTimeout(() => fabRef.current && fabRef.current.focus(), 0); };
    }, [open]);
    useEffect(() => { if (!items.length) setOpen(false); }, [items.length]);
    // 清空要按兩次：第一次變成「確定清空？」，4 秒內沒按就恢復
    useEffect(() => {
        if (!confirmClear) return;
        const t = setTimeout(() => setConfirmClear(false), 4000);
        return () => clearTimeout(t);
    }, [confirmClear]);

    if (!items.length) return null;

    const text = Q.render(items, opts);
    const copy = async () => {
        const ok = await UI.copyText(text);
        UI.toast(ok ? `已複製引用籃文字（${items.length} 項，可直接貼到臉書）` : '複製失敗，請手動選取下方文字');
    };
    // 清單上的一行摘要：指標：數值（比較項目列出各對象）
    const summary = (it) => {
        const ps = it.parts || [it];
        const v = (x) => x ? `${x.value}${x.unit || ''}` : '—';
        const vals = it.kind === 'compare'
            ? ps[0].values.map((x, i) => `${x.tag} ${ps.map(p => v(p.values[i])).join('／')}`).join(it.sep === 'vs.' ? ' vs. ' : ' → ')
            : ps.map(p => v(p.values[0])).join('／');
        return `${ps.map(p => p.label).join('／')}：${vals}`;
    };

    const iconBtn = 'inline-flex h-7 w-7 shrink-0 items-center justify-center border border-white/10 text-[12px] text-slate-400 hover:border-white/30 hover:text-slate-100 disabled:opacity-30 disabled:hover:border-white/10 disabled:hover:text-slate-400';
    const OPT_ROWS = [
        { k: 'header', label: '整段標頭', options: [{ value: 'none', label: '無' }, { value: 'key', label: '●關鍵數據：' }, { value: 'custom', label: '自訂' }] },
        { k: 'prefix', label: '行首', options: [{ value: '※', label: '※' }, { value: '•', label: '•' }, { value: '', label: '無' }] },
        { k: 'names', label: '指標名稱', options: [{ value: 'zh', label: '中文' }, { value: 'en', label: '原文' }, { value: 'both', label: '中文（原文）' }] },
        { k: 'cmpStyle', label: '前後比較', options: [{ value: 'arrow', label: 'A → B' }, { value: 'delta', label: '差值' }, { value: 'trend', label: '→ 加📈📉' }] },
        { k: 'rank', label: '名次', options: [{ value: 'on', label: '帶名次' }, { value: 'off', label: '不帶' }], bool: true },
        { k: 'ptStyle', label: 'Playtype 名次', options: [{ value: 'league', label: '聯盟第N' }, { value: 'pr', label: 'PR' }] },
        { k: 'asOfNote', label: '統計日期', options: [{ value: 'off', label: '不附' }, { value: 'on', label: '附「統計至」' }], bool: true },
        { k: 'source', label: '來源網址', options: [{ value: 'off', label: '不附' }, { value: 'on', label: '附上' }], bool: true },
    ];

    return (<>
        {!open && (
            <button ref={fabRef} type="button" onClick={() => setOpen(true)} aria-label={`開啟引用籃（${items.length} 項）`}
                style={{ bottom: 'calc(1rem + env(safe-area-inset-bottom))' }}
                className="fixed right-4 z-40 inline-flex h-12 min-w-[48px] items-center gap-2 rounded-full bg-[#12A150] px-4 text-[14px] font-medium text-[#0A1626] shadow-2xl hover:brightness-110">
                <span aria-hidden="true">引用籃</span>
                <span className="inline-flex h-6 min-w-[24px] items-center justify-center rounded-full bg-[#0A1626] px-1.5 font-mono text-[12px] text-[#12A150]">{items.length}</span>
            </button>
        )}
        {open && (
            <div className="fixed inset-0 z-[60]">
                <div className="absolute inset-0 bg-black/50" onClick={() => setOpen(false)} aria-hidden="true"></div>
                <div ref={panelRef} tabIndex={-1} role="dialog" aria-modal="true" aria-label="引用籃"
                    className="absolute inset-y-0 right-0 flex w-full flex-col border-l border-white/15 bg-[#0C1A2E] shadow-2xl outline-none sm:w-[460px]">
                    <header className="flex items-center justify-between gap-3 border-b border-white/10 px-4 py-3">
                        <div>
                            <div className="text-[15px] font-medium text-slate-100">引用籃 <span className="font-mono text-[12px] text-slate-400">{items.length} 項</span></div>
                            <div className="text-[11px] text-slate-500">貼文用純文字：調好順序與格式後一鍵複製</div>
                        </div>
                        <button type="button" onClick={() => setOpen(false)} aria-label="關閉引用籃"
                            className="inline-flex h-8 w-8 items-center justify-center text-[18px] text-slate-400 hover:text-slate-100">×</button>
                    </header>

                    <div className="min-h-0 flex-1 space-y-5 overflow-y-auto px-4 py-4">
                        <ol className="border-t border-white/[0.08]">
                            {items.map((it, i) => {
                                const next = items[i + 1];
                                return (
                                    <li key={it.id} className="flex items-start gap-2 border-b border-white/[0.08] py-2">
                                        <div className="min-w-0 flex-1">
                                            <div className="break-words text-[13px] text-slate-100">{summary(it)}</div>
                                            <div className="font-mono text-[10px] text-slate-500">{[it.subject, it.context].filter(Boolean).join('｜')}{it.parts ? ' · 已合併' : ''}</div>
                                        </div>
                                        <div className="flex shrink-0 flex-wrap justify-end gap-1">
                                            <button type="button" className={iconBtn} aria-label="上移" disabled={i === 0} onClick={() => Q.move(it.id, -1)}>↑</button>
                                            <button type="button" className={iconBtn} aria-label="下移" disabled={i === items.length - 1} onClick={() => Q.move(it.id, 1)}>↓</button>
                                            {it.parts
                                                ? <button type="button" className={`${iconBtn} w-auto px-1.5`} onClick={() => Q.split(it.id)}>拆開</button>
                                                : <button type="button" className={`${iconBtn} w-auto px-1.5`} disabled={!Q.canMerge(it, next)} onClick={() => Q.merge(it.id)}
                                                    title={Q.canMerge(it, next) ? '和下一項寫成同一行（例：出手數／命中率）' : '下一項的主體、情境或比較對象不同，不能合併'}>併下一項</button>}
                                            <button type="button" className={iconBtn} aria-label="刪除" onClick={() => Q.remove(it.id)}>✕</button>
                                        </div>
                                    </li>
                                );
                            })}
                        </ol>

                        <div className="space-y-2.5">
                            {OPT_ROWS.map(r => (
                                <div key={r.k} className="flex flex-wrap items-center gap-x-3 gap-y-1">
                                    <span className="w-20 shrink-0 text-[11px] text-slate-400">{r.label}</span>
                                    <UI.Seg size="sm" ariaLabel={r.label} options={r.options}
                                        value={r.bool ? (opts[r.k] ? 'on' : 'off') : opts[r.k]}
                                        onChange={(v) => Q.setOpts({ [r.k]: r.bool ? v === 'on' : v })} />
                                </div>
                            ))}
                            {opts.header === 'custom' && (
                                <input type="text" aria-label="自訂標頭" value={opts.headerText} placeholder="例：●關鍵數據（G1 vs. 熱火）："
                                    onChange={(e) => Q.setOpts({ headerText: e.target.value })}
                                    className="w-full border border-white/15 bg-transparent px-2.5 py-1.5 text-[13px] text-slate-100 placeholder:text-slate-600 focus:border-[#12A150] focus:outline-none" />
                            )}
                        </div>

                        <div>
                            <div className="mb-1.5 text-[11px] text-slate-400">預覽</div>
                            <textarea readOnly value={text} rows={Math.min(16, text.split('\n').length + 1)} aria-label="引用文字預覽"
                                className="w-full resize-y border border-white/15 bg-[#0A1626] p-2.5 font-sans text-[13px] leading-relaxed text-slate-100 focus:border-[#12A150] focus:outline-none" />
                        </div>
                    </div>

                    <footer className="flex items-center justify-between gap-3 border-t border-white/10 px-4 py-3"
                        style={{ paddingBottom: 'calc(0.75rem + env(safe-area-inset-bottom))' }}>
                        <button type="button" onClick={() => { if (confirmClear) { Q.clear(); setConfirmClear(false); UI.toast('已清空引用籃'); } else setConfirmClear(true); }}
                            className={`inline-flex min-h-[32px] items-center border px-3 text-[12px] ${confirmClear ? 'border-[#EF4444] text-[#EF4444]' : 'border-white/15 text-slate-400 hover:border-white/30 hover:text-slate-100'}`}>
                            {confirmClear ? '確定清空？再按一次' : '清空'}
                        </button>
                        <button type="button" onClick={copy}
                            className="inline-flex min-h-[36px] items-center bg-[#12A150] px-4 text-[14px] font-medium text-[#0A1626] hover:brightness-110">複製文字</button>
                    </footer>
                </div>
            </div>
        )}
    </>);
};

window.QuoteBasket = QuoteBasket;


