// ---------- constants.js ----------
// 全域常數
window.PlayTypesList = ["Transition", "Isolation", "PRBallHandler", "PRRollMan", "Postup", "Spotup", "Handoff", "Cut", "OffScreen", "OffRebound", "Misc"];
// Playtype 中文名（與 glossary.js 的 PT_* 定義同名）；畫面一律「中文 + 小字原文」，查不到退回原文
const PT_ZH = { Transition: '轉換進攻', Isolation: '單打', PRBallHandler: '擋拆持球者', PRRollMan: '擋拆掩護者', Postup: '背框單打',
    Spotup: '定點投籃', Handoff: '手遞手', Cut: '空切', OffScreen: '繞掩護', OffRebound: '進攻籃板補進', Misc: '其他' };
window.ptName = (t) => PT_ZH[t] || t;
// 小樣本提示：場數少於門檻（開季、季中轉入）時在 Playtype／季平均旁提醒數值波動大；沒有場數或夠多回 null
window.SMALL_SAMPLE_GAMES = 10;
window.smallSampleNote = (n, what = '數據') => (typeof n === 'number' && n > 0 && n < window.SMALL_SAMPLE_GAMES)
    ? `${what}只有 ${n} 場，樣本小、數值波動大（尤其百分位與命中率），看趨勢請等累積到 ${window.SMALL_SAMPLE_GAMES} 場以上` : null;
// 一位小數，-0.04 這類捨入後為 0 的負數不顯示成「-0.0」
window.fix1 = (v) => { const s = Number(v).toFixed(1); return s === '-0.0' ? '0.0' : s; };

// 名稱比對用 key：去句點/重音/多餘空白後小寫。
// 必要性：同一人的名字在不同季的 API 回傳不一致
// （2025-26 是 "Terrence Shannon Jr."，2026-27 是 "Terrence Shannon Jr"），
// 而球員資料以 playerName 為主鍵，不正規化就會對不上。
window.nameKey = (n) => String(n || '')
    .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')   // 去重音: Jokic
    .replace(/[.\u2019']/g, '')                            // 去句點與彎/直撇號
    .replace(/\s+/g, ' ').trim().toLowerCase();
// 網址用的名字寫法：nameKey 後非英數字一律換 -（Monté Morris → monte-morris、T.J. Warren → tj-warren）。
// 只給人看（網址 p=ID-名字），對人一律用前面的 ID，見 urlState.js
window.nameSlug = (n) => window.nameKey(n).replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

// 賽季階段判斷（前端版本，對應 fetch_data.py 的 get_season_type()）
// 使用美東時間 UTC-5（不處理 DST，誤差可忍）
window.getSeasonPhase = function (date) {
    const d = date || new Date();
    const eastTime = new Date(d.getTime() - 5 * 3600 * 1000);
    const m = eastTime.getUTCMonth() + 1;
    const day = eastTime.getUTCDate();
    if ((m === 10 && day >= 20) || m === 11 || m === 12 || m === 1 || m === 2 || m === 3 || (m === 4 && day <= 15)) {
        return { type: 'regular', label: '例行賽', inSeason: true };
    } else if ((m === 4 && day >= 16) || m === 5 || (m === 6 && day <= 20)) {
        return { type: 'playoffs', label: '季後賽', inSeason: true };
    } else {
        return { type: null, label: '休賽期', inSeason: false };
    }
};
// 「當季」賽季字串：美東 10/20（例行賽起點，與 getSeasonPhase 同界）切換到新賽季，
// 休賽期仍指向剛打完的那季。必須與 scripts/nba_common.py 的 get_current_season() 同規則
// （每日快照、投籃熱圖 doc id、bundle id 都靠它對上），改界線要兩邊一起改。
window.seasonForDate = function (date) {
    const d = date || new Date();
    const eastTime = new Date(d.getTime() - 5 * 3600 * 1000);
    const y = eastTime.getUTCFullYear(), m = eastTime.getUTCMonth() + 1, day = eastTime.getUTCDate();
    const start = (m > 10 || (m === 10 && day >= 20)) ? y : y - 1;
    return `${start}-${String((start + 1) % 100).padStart(2, '0')}`;
};
window.CURRENT_SEASON = window.seasonForDate();
// 薪資賽季（聯盟年度）：美東 7/1 切換（休賽期就看下一季的合約與門檻）。
// 必須與 scripts/nba_common.py 的 get_roster_season() 同規則（sync_salary.py 用它判斷哪些賽季必須有門檻）
window.capSeasonForDate = function (date) {
    const d = date || new Date();
    const eastTime = new Date(d.getTime() - 5 * 3600 * 1000);
    const y = eastTime.getUTCFullYear(), m = eastTime.getUTCMonth() + 1;
    const start = m >= 7 ? y : y - 1;
    return `${start}-${String((start + 1) % 100).padStart(2, '0')}`;
};
// 賽季選擇器選項：current = 當季每日快照，其餘為歷史終點快照。
// 單一來源：跨季比較清單（COMPARISON_SEASON_OPTIONS）由 HISTORY_SEASON_OPTIONS 加上當季組成，勿另建第二份。
// 不變式：option.key === Firestore 的 history docId（`${season}_${type}`）
// short 用「例行／季後」兩字：單字「季」會被讀成「賽季」。刊頭選單只列年份（SEASON_YEAR_OPTIONS），賽別由例行/季後切換決定
window.HISTORY_SEASONS = ['2025-26', '2024-25', '2023-24', '2022-23'];
window.HISTORY_SEASON_OPTIONS = window.HISTORY_SEASONS.flatMap(s =>
    [['playoffs', '季後賽', '季後'], ['regular', '例行賽', '例行']].map(([t, l, sh]) => ({
        key: `${s}_${t}`, season: s, type: t,
        label: `${s} ${l}`, short: `${s.slice(2)}${sh}`,
        order: parseInt(s.slice(0, 4), 10) * 10 + (t === 'playoffs' ? 1 : 0),  // ComparisonTab 折線 X 軸排序用
    }))
);
// 跨季比較清單：當季（每日快照最新一份，key 'current_賽別'）＋歷史終點快照。
// 當季季後賽要等例行賽期結束才列；當季已進 HISTORY_SEASONS（已建終點快照）就只用歷史那份
window.COMPARISON_SEASON_OPTIONS = (() => {
    const cur = window.CURRENT_SEASON;
    if (window.HISTORY_SEASONS.includes(cur)) return window.HISTORY_SEASON_OPTIONS;
    const types = window.getSeasonPhase().type === 'regular' ? [['regular', '例行賽', '例行']]
        : [['playoffs', '季後賽', '季後'], ['regular', '例行賽', '例行']];
    return [...types.map(([t, l, sh]) => ({
        key: `current_${t}`, season: cur, type: t, isCurrent: true,
        label: `${cur} ${l}`, short: `${cur.slice(2)}${sh}`,
        order: parseInt(cur.slice(0, 4), 10) * 10 + (t === 'playoffs' ? 1 : 0),
    })), ...window.HISTORY_SEASON_OPTIONS];
})();
window.SEASON_OPTIONS = [
    // 休賽期時該季已經打完，寫「進行中」是錯的（getSeasonPhase 必須定義在本行之前）
    {
        key: 'current', isCurrent: true,
        label: `${window.CURRENT_SEASON} ${window.getSeasonPhase().inSeason ? '進行中' : '最終'}`,
    },
    ...window.HISTORY_SEASON_OPTIONS,
];
// 刊頭賽季選單：只列年份（賽別交給旁邊的例行/季後切換）。value 'current'＝當季每日快照，其餘＝HISTORY_SEASONS
window.SEASON_YEAR_OPTIONS = [
    { value: 'current', label: window.SEASON_OPTIONS[0].label },
    ...window.HISTORY_SEASONS.map(s => ({ value: s, label: s })),
];

// 新援探測順序：找該球員最近一個「真的有資料」的賽季。
