window.TEAM_ABBR = 'MIN';
window.teamTag = (abbr) => (!abbr || abbr === window.TEAM_ABBR) ? '' : `@${abbr}`;
window.NA_REASON = {
    CROSS_TEAM: '跨隊資料不適用：NBA API 的最近防守者（Defense Dashboard）/ On-Off 需綁定 TeamID，該季此球員不在灰狼，無法取得',
};
window.NA_BADGE = '跨隊不適用';

// teamAbbr 只有在 isNewcomer 時才可信。
// 理由：backfill_history.py 只對新援逐人查生涯分隊（Step 5b）；其餘球員的 teamAbbr
// 直接來自 leaguedashplayerstats 的 TEAM_ABBREVIATION，那個欄位只標「最後一隊」，
// 歷史賽季中途被交易走的灰狼球員會帶著別隊縮寫 → 無條件顯示會標錯人。
window.tagOfMeta = (meta) => (meta && meta.isNewcomer) ? window.teamTag(meta.teamAbbr) : '';

// normalizeHistoryPlayer 會把這些 metadata 注入每個類別 dict，
// 因此「這個類別有沒有真資料」不能用 Object.keys().length，必須排除掉它們
window.PLAYER_META_KEYS = ['playerId', 'isCurrentRoster', 'teamAbbr'];
window.hasRealData = (obj) => !!obj && Object.keys(obj).some(k => !window.PLAYER_META_KEYS.includes(k));

// 歷史快照的 localStorage 快取。
// 版本號：後端 backfill 改變結構時必須 +1，否則使用者瀏覽器會永遠讀到舊資料
// （舊版程式只要 cache 存在就 return，不再打 Firestore）。
// 不只「結構」變更要 +1，**每次重跑 backfill_history.py 也要 +1**：
// 快取只以 docId 為 key，內容變了（例如回補後多出新援）而版本沒動，
// 已開過頁面的使用者在 TTL 內完全看不到新資料。
window.HISTORY_CACHE_VER = 5;                 // v5 = 各季歷史快照補齊 Hustle 欄位（2026-10-23）；v4 = 回補納入新援
window.HISTORY_CACHE_TTL = 24 * 3600 * 1000;
const _histKey = (docId) => `wt_history_v${window.HISTORY_CACHE_VER}_${docId}`;
window.purgeHistoryCache = (all) => {
    try {
        Object.keys(localStorage).forEach(k => {
            if (k.startsWith('wt_history_') && (all || !k.startsWith(`wt_history_v${window.HISTORY_CACHE_VER}_`)))
                localStorage.removeItem(k);
        });
    } catch (e) { /* private mode / quota */ }
};
window.readHistoryCache = (docId) => {
    try {
        const o = JSON.parse(localStorage.getItem(_histKey(docId)) || 'null');
        if (!o || o.v !== window.HISTORY_CACHE_VER) return null;
        if (Date.now() - o.t > window.HISTORY_CACHE_TTL) return null;
        return o.d;
    } catch (e) { return null; }
};
window.writeHistoryCache = (docId, d) => {
    try { localStorage.setItem(_histKey(docId), JSON.stringify({ v: window.HISTORY_CACHE_VER, t: Date.now(), d })); }
    catch (e) { window.purgeHistoryCache(true); }   // quota 滿 → 清掉全部歷史快取
};
window.purgeHistoryCache(false);   // 載入時立即清掉舊版 key

// 每日快照的讀取起始日：doc id 就是日期字串，故以 doc id 範圍過濾出「當季」。
// 為什麼不用 orderBy(documentId(),'desc') + limit：那需要建 Firestore 複合索引，缺索引時查詢被拒、整個面板空掉。
// __name__ 升冪是 Firestore 預設索引，範圍查詢免建索引（已實測）。
// 以賽季起始年的 7/1 為界：完整涵蓋例行賽+季後賽（打到隔年 6 月），
// 又能永久擋住 collection 隨賽季累積而無限成長。
window.SNAPSHOT_SINCE = `${parseInt(window.CURRENT_SEASON.slice(0, 4), 10)}-07-01`;
// 上界＝隔年 6/30，涵蓋到總冠軍賽結束。除了鎖定單一賽季，也擋掉非日期的 doc id
// （'latest'、'meta' 之類字母 id 字典序都大於數字，只有下界會把它們一起撈進來，
//   之後 new Date(id) 變 NaN 污染排序）
window.SNAPSHOT_UNTIL = `${parseInt(window.CURRENT_SEASON.slice(0, 4), 10) + 1}-06-30`;
// 開站時只讀「最近幾天」的快照（當期＋前一期算增減就夠），其餘等需要時才補讀整季（見 App.js snapFull）。
// 賽季中：今天往前 10 天（每日快照，約 10 份）。
// 休賽期（今天已過賽季上界 6/30）：從 6/30 往前 30 天——總冠軍賽結束日每年不同（約 6 月中），要留足夠緩衝。
// 窗口內湊不到兩份時，App.js 會自動改讀整季，不會顯示成沒資料
window.snapshotWindowStart = () => {
    const pad = (n) => String(n).padStart(2, '0');
    const now = new Date();
    const today = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
    const off = today > window.SNAPSHOT_UNTIL;
    const d = new Date((off ? window.SNAPSHOT_UNTIL : today) + 'T00:00:00Z');
    d.setUTCDate(d.getUTCDate() - (off ? 30 : 10));
    const start = d.toISOString().slice(0, 10);
    return start > window.SNAPSHOT_SINCE ? start : window.SNAPSHOT_SINCE;
};

